def solve(case, api):
    import math

    names = ('w_in_um', 'w_load_um', 'w_stage_um', 'w_sink_um',
             'ibias_ua', 'cc_pf', 'rz_ohm')
    bounds = ((2., 300.), (2., 300.), (2., 1500.), (2., 500.),
              (2., 100.), (.2, 30.), (0., 20000.))

    def clamp(p):
        return {k: min(bounds[i][1], max(bounds[i][0], float(p[k])))
                for i, k in enumerate(names)}

    def values(obj):
        """Find reported metrics even if the host nests them in a result object."""
        found = {}
        def walk(x):
            if isinstance(x, dict):
                for k, v in x.items():
                    if k in ('gain_db', 'unity_mhz', 'phase_margin_deg',
                             'power_mw', 'open_loop_output_v',
                             'settled_error_mv', 'overshoot_percent'):
                        try:
                            found[k] = float(v)
                        except (TypeError, ValueError):
                            pass
                    if isinstance(v, (dict, list, tuple)):
                        walk(v)
            elif isinstance(x, (list, tuple)):
                for v in x:
                    walk(v)
        walk(obj)
        return found

    req = getattr(case, 'requirements', {}) or {}
    def requirement(key, default):
        try:
            return float(req.get(key, default))
        except Exception:
            return default

    gmin = requirement('gain_db_min', 60.)
    umin = requirement('unity_mhz_min', 5.)
    pmin = requirement('phase_margin_deg_min', 55.)
    pmax = requirement('power_mw_max', .65)
    emin = requirement('settled_error_mv_max', 1.)
    omax = requirement('overshoot_percent_max', 25.)
    vdd = float(getattr(case, 'supply_v', 1.8))

    def score(m):
        # Lower is better. Penalties are continuous, so imperfect first
        # candidates still guide the limited search toward useful regions.
        def get(k, fallback):
            return m.get(k, fallback)
        g = get('gain_db', -100.)
        u = get('unity_mhz', 0.)
        ph = get('phase_margin_deg', -100.)
        pw = get('power_mw', 100.)
        out = get('open_loop_output_v', -10.)
        err = get('settled_error_mv', 100.)
        ov = get('overshoot_percent', 100.)
        return (max(0., gmin-g)/10. + max(0., umin-u)/umin * 2.
                + max(0., pmin-ph)/20. + max(0., pw-pmax)/pmax * 2.
                + max(0., .15-out, out-(vdd-.15)) * 3.
                + max(0., err-emin)/emin + max(0., ov-omax)/omax
                # Prefer a useful output operating point away from either rail.
                + abs(out-vdd*.5)/max(vdd, .1)*.08)

    # Initial points cover plausible current levels and second-stage current
    # ratios. Later points perturb the strongest observed candidate.
    starts = [
        (60, 25, 100, 10, 20, 1.5, 5000),
        (60, 25, 100, 20, 20, 1.0, 5000),
        (60, 25, 200, 20, 20, 1.5, 5000),
        (60, 25, 50, 8, 20, 1.0, 8000),
        (80, 35, 150, 20, 35, 1.0, 3000),
        (40, 20, 100, 10, 35, .7, 5000),
        (100, 35, 200, 30, 35, 1.5, 3000),
        (80, 25, 100, 10, 12, .8, 8000),
        (60, 30, 250, 25, 50, 2.0, 2000),
        (120, 40, 300, 30, 50, 1.0, 3000),
        (80, 25, 150, 15, 25, .5, 10000),
        (50, 25, 150, 15, 25, 3.0, 5000),
    ]
    best = clamp(dict(zip(names, starts[0])))
    best_score = float('inf')
    used = 0
    for i in range(12):
        if i < len(starts):
            p = clamp(dict(zip(names, starts[i])))
        else:
            p = best
        try:
            result = api.simulate(p)
            used += 1
            s = score(values(result))
            if s < best_score:
                best_score, best = s, p
        except Exception:
            used += 1
            if used >= 12:
                break
    return best

import math


def solve(case, api):
    def field(obj, name, default):
        if isinstance(obj, dict):
            return obj.get(name, default)
        return getattr(obj, name, default)

    vdd = float(field(case, 'supply_v', 1.8))
    load = float(field(case, 'load_pf', 5.0))
    temp = float(field(case, 'temperature_c', 27.0))
    mobility = float(field(case, 'mobility_scale', 1.0))
    req = field(case, 'requirements', {})
    limits = {
        'gain_db': float(field(req, 'gain_db_min', 60.0)),
        'unity_mhz': float(field(req, 'unity_mhz_min', 5.0)),
        'phase_margin_deg': float(field(req, 'phase_margin_deg_min', 55.0)),
        'power_mw': float(field(req, 'power_mw_max', 0.65)),
        'settled_error_mv': float(field(req, 'settled_error_mv_max', 1.0)),
        'overshoot_percent': float(field(req, 'overshoot_percent_max', 25.0))
    }
    bounds = {
        'w_in_um': (2.0, 300.0), 'w_load_um': (2.0, 300.0),
        'w_stage_um': (2.0, 1500.0), 'w_sink_um': (2.0, 500.0),
        'ibias_ua': (2.0, 100.0), 'cc_pf': (0.2, 30.0),
        'rz_ohm': (0.0, 20000.0)
    }

    def clip(p):
        return {k: float(max(lo, min(hi, p[k])))
                for k, (lo, hi) in bounds.items()}

    # LEVEL=1 mobility temperature scaling is adequate for initial sizing;
    # actual simulator measurements take precedence below.
    effective_mobility = max(0.15, mobility *
                             (300.15 / (273.15 + temp)) ** 1.5)
    kn = 200e-6 * effective_mobility
    kp = 90e-6 * effective_mobility
    bias = 20.0
    ratio_limit = 2.0 * (0.80 * limits['power_mw'] * 1000.0 /
                         (vdd * bias) - 2.0)
    ratio = max(6.0, min(15.0 * max(1.0, load / 6.0), ratio_limit))
    win, wload = 80.0, 12.0
    gm1 = math.sqrt(kn * win * bias * 1e-6)
    target_mhz = max(8.0, 1.5 * limits['unity_mhz'])
    cc = gm1 / (2.0 * math.pi * target_mhz * 1e6) * 1e12
    tail_v = 0.9 - 0.45 - math.sqrt(bias * 1e-6 / (kn * win))
    diode_drop = 0.45 + math.sqrt(bias * 1e-6 / (kp * wload))
    sink = 5.0 * ratio * (1.0 + 0.04 * tail_v) / (1.0 + 0.04 * diode_drop)
    p = clip({
        'w_in_um': win, 'w_load_um': wload,
        'w_stage_um': ratio * wload, 'w_sink_um': sink,
        'ibias_ua': bias, 'cc_pf': cc, 'rz_ohm': 0.0
    })

    def stage_gm(q):
        current = q['ibias_ua'] * 1e-6 * q['w_sink_um'] / 10.0
        return math.sqrt(max(1e-16, 2.0 * kp * q['w_stage_um'] * current))

    p['rz_ohm'] = min(20000.0, 1.0 / stage_gm(p))

    def metrics(result):
        out = {}
        wanted = set(limits) | {'open_loop_output_v'}
        def visit(x, depth=0):
            if depth > 5:
                return
            if isinstance(x, dict):
                for k, value in x.items():
                    if k in wanted:
                        try:
                            number = float(value)
                            if math.isfinite(number):
                                out[k] = number
                        except (TypeError, ValueError):
                            pass
                    elif isinstance(value, (dict, list, tuple)):
                        visit(value, depth + 1)
            elif isinstance(x, (list, tuple)):
                for value in x:
                    visit(value, depth + 1)
        visit(result)
        for key in wanted:
            if key not in out and hasattr(result, key):
                try:
                    value = float(getattr(result, key))
                    if math.isfinite(value):
                        out[key] = value
                except (TypeError, ValueError):
                    pass
        return out

    def violations(m):
        bad = {}
        for key, limit in limits.items():
            if key not in m:
                continue
            if key in ('gain_db', 'unity_mhz', 'phase_margin_deg'):
                bad[key] = max(0.0, (limit - m[key]) / max(1.0, limit))
            else:
                bad[key] = max(0.0, (m[key] - limit) / max(0.1, limit))
        if 'open_loop_output_v' in m:
            out = m['open_loop_output_v']
            bad['bias'] = max(0.0, 0.15 - out, out - (vdd - 0.15)) / 0.15
        return bad

    best = dict(p)
    best_score = float('inf')
    for iteration in range(12):
        p = clip(p)
        try:
            result = api.simulate(dict(p))
        except Exception:
            return best
        m = metrics(result)
        if not m:
            return best
        bad = violations(m)
        score = sum(bad.values()) + 2.0 * max(bad.values(), default=0.0)
        if score < best_score:
            best_score, best = score, dict(p)
        if len(m) == 7 and score == 0.0:
            return dict(p)
        if score == 0.0:
            return dict(p)

        q = dict(p)
        # Correct output current balance before changing AC sizing.
        if bad.get('bias', 0.0) > 0.0:
            out = m['open_loop_output_v']
            correction = math.exp(0.077 * (out - 0.5 * vdd))
            q['w_sink_um'] *= correction
            p = q
            continue

        if bad.get('power_mw', 0.0) > 0.0:
            factor = max(0.35, min(0.9, 0.88 * limits['power_mw'] / m['power_mw']))
            q['ibias_ua'] *= factor
            # Preserve transconductance while reducing branch currents.
            q['w_in_um'] /= factor
            q['w_load_um'] /= factor
            q['w_stage_um'] /= factor
        else:
            if bad.get('gain_db', 0.0) > 0.0:
                q['w_in_um'] *= 1.6
                q['w_load_um'] *= 1.6
                q['w_stage_um'] *= 1.6
                q['cc_pf'] *= math.sqrt(1.6)

            unstable = (bad.get('phase_margin_deg', 0.0) > 0.0 or
                        bad.get('overshoot_percent', 0.0) > 0.0)
            if unstable:
                # Raise the output pole when power headroom permits.
                power = m.get('power_mw', limits['power_mw'])
                increase = min(1.4, max(1.0, 0.90 * limits['power_mw'] / max(power, 1e-6)))
                q['w_stage_um'] *= increase
                q['w_sink_um'] *= increase
                q['cc_pf'] *= 1.15
                gm6 = stage_gm(q)
                # A modest LHP zero supplies additional phase lead.
                q['rz_ohm'] = (1.0 + 0.7 * load / q['cc_pf']) / gm6
            elif bad.get('unity_mhz', 0.0) > 0.0:
                measured = max(0.01, m['unity_mhz'])
                factor = measured / (1.3 * limits['unity_mhz'])
                q['cc_pf'] *= max(0.35, min(0.9, factor))
                q['rz_ohm'] = 1.0 / stage_gm(q)
            elif bad.get('settled_error_mv', 0.0) > 0.0:
                # With an otherwise stable loop, improve its speed and gain.
                q['w_in_um'] *= 1.3
                q['cc_pf'] *= 0.9
                q['rz_ohm'] = (1.0 + 0.3 * load / q['cc_pf']) / stage_gm(q)

        p = q
    return best

def solve(case, api):
    density = float(case['density_kg_m3'])
    viscosity = float(case['dynamic_viscosity_pa_s'])
    return {
        'config': {
            'length_m': float(case['length_m']),
            'lid_speed_m_per_s': float(case['lid_speed_m_per_s']),
            'kinematic_viscosity_m2_per_s': viscosity / density,
            'wall_velocity_m_per_s': {
                'top': [float(case['lid_speed_m_per_s']), 0.0],
                'bottom': [0.0, 0.0],
                'left': [0.0, 0.0],
                'right': [0.0, 0.0],
            },
            'mesh_nodes': case['required_mesh_nodes'],
            'advection': 'central',
            'steady_tolerance': 1e-7,
            'max_steps': 50000,
        }
    }

